function LanternRechargeDialog:Awake()
    SetButtonAction(self.TxtPlayState, Bind(self, self.OnBtnRule))
    SetButtonAction(self.BtnGet, Bind(self, self.OnBtnLight))
    SetButtonAction(self.BtnLock, Bind(self, self.OnBtnLight))

    --SetButtonAction(self.BtnLook, Bind(self, self.OnBtnLook))
    --SetButtonAction(self.AvailableBtnNode, Bind(self, self.OnDrawBox))
end

function LanternRechargeDialog:InitData()
    self._vo = LanternRechargeUtils.GetLanternRechargeVo(self._serverData.activityLanternConf.id)
end

function LanternRechargeDialog:Refresh(data)
    if isNull(data) then
        return
    end

    self._data = data
    GameUtils.Request(Interfaces.ActivityLantern, {activityUuid = self._data.id}, function(request, response)
        if checkInt(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        self._serverData = jsonData

        self:InitData()
        self:FillSelf()

        CfUtils.RefreshTopGoods({self._vo.token})

        local isCanDraw = ((checkNumber(self._serverData.freeTimes) > 0) or (GoodsUtils.GetThingNo(LanternRechargeUtils.GetConsumeId()) > 0)) 
        ActivityUtils.UpdateActivityMainRedPointState(self._data.id, isCanDraw and 0 or -1)
    end)
end

function LanternRechargeDialog:FillSelf()
    local startTime = self._data.startTime
    local closeTime = self._data.closeTime
    CfUtils.FillText(self.TxtTime2, ActivityUtils.ConventActivityDurationTime(startTime, closeTime))
    CfUtils.FillText(self.TxtContent, self._data.detail)
    if isNotNull(self._data.titleImage) and string.len(self._data.titleImage) > 0 then
        local rawImage = KTool.GetComponent(self.ImgTitleName.gameObject, typeof(CS.UnityEngine.UI.RawImage))
        if isNotNull(rawImage) then
            rawImage.enabled = true
        end
        CfUtils.FillWebRawImage(self.ImgTitleName, self._data.titleImage)    
    end
    CfUtils.FillText(self.TxtTotalNumber, GoodsUtils.GetThingNo(LanternRechargeUtils.GetConsumeId()))
    CfUtils.FillText(self.TxtTotal , localize("玲珑花灯总计"))
    CfUtils.FillText(self.TxtNumber.transform.parent , localize("今日可获取玲珑花灯："))

    CfUtils.FillText(self.TxtTodayNumber, self._serverData.todayPayDiamondNum)

    -- print(LanternRechargeUtils.GetMaxGetNum())
    CfUtils.FillText(self.TxtNumber, self._serverData.lanternGetRemainTimesLeft.."/"..LanternRechargeUtils.GetMaxGetNum())
    CfUtils.FillText(self.TxtTimeNumber, self._serverData.freeTimes.."/"..LanternRechargeUtils.GetFreeTime())
    local imageComp =  self.ImgIconlamp.transform:GetComponent(typeof(CS.UnityEngine.UI.Image))
    imageComp.enabled = true
    CfUtils.FillImage(self.ImgIconlamp ,GoodsConfMgr:GetPhotoPathById(self._serverData.activityLanternConf.token[1]) )
    CfUtils.SetActive(self.LockNode, true)
    local isFree = checkNumber(self._serverData.freeTimes) > 0
    CfUtils.SetActive(self.TxtTime, isFree)
    local isCanDraw = ((checkNumber(self._serverData.freeTimes) > 0) or (GoodsUtils.GetThingNo(LanternRechargeUtils.GetConsumeId()) > 0)) 
    CfUtils.SetActive(self.BtnLock, not isCanDraw)
    CfUtils.SetActive(self.BtnGet, isCanDraw)

    CfUtils.SetActive(self.NumberGroup, not isFree)
    CfUtils.FillText(self.TxtTimeNumber2, GoodsUtils.GetThingNo(LanternRechargeUtils.GetConsumeId()).."/"..LanternRechargeUtils.GetConsumeNum())

    local img = self.ImgProgress:GetComponent(typeof(CS.UnityEngine.UI.Image))
    local num1, num2 = math.modf(checkNumber(self._serverData.todayPayDiamondNum) / LanternRechargeUtils.GetScaleNum()) 
    img.fillAmount = num2 / LanternRechargeUtils.GetScaleNum()

    CfUtils.SetActive(self.Container.transform:Find("RightPanel/LampGroup/ImgLamp/ImgLamp4"), isCanDraw)
    CfUtils.SetActive(self.Container.transform:Find("RightPanel/LampGroup/ImgLampNew/ImgLamp4"), isCanDraw)

    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(self._vo.token) 
    local go = KTool.GetOrAddComponent(self.Container.transform:Find("RightPanel/LockNode/NumberGroup/ImgLamp").gameObject, typeof(ImageAlterable))
    CfUtils.FillImage(go, goodsVo.photoPath)
end

function LanternRechargeDialog:OnBtnRule()
    if checkNumber(self._vo.ruleID) > 0 then
        CfUtils.ShowModuleToast(self._vo.ruleID)
    end
end

function LanternRechargeDialog:OnBtnLight()
    if self._isClick then
        return
    end
    local isCanDraw = ((checkNumber(self._serverData.freeTimes) > 0) or (GoodsUtils.GetThingNo(LanternRechargeUtils.GetConsumeId()) > 0)) 
    if not isCanDraw then
        local str = ""
        if checkNumber(self._serverData.lanternGetRemainTimesLeft) <= 0 then
            str = localize("今日花灯获取数已达上限")
        end

        GameUtils.SecondConfirm(localize("花灯数量不足，前往商城，充值虹晶获取"), function()
            OverseaStoreUtils.OpenStore(OverseaStoreConstants.StoreType.TopUp, {{id =  Constants.UITypeIds.UIActivityMainDialog}}, {hideToggle = false})
        end, function()
            
        end, nil, nil, nil, nil, str)
        return
    end

    self._isClick = true 
    GameUtils.Request(Interfaces.ActivityDrawLantern, {activityUuid = self._data.id}, function(request, response)
        if checkInt(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data

        if #checkTable(jsonData.rewards) > 0 then
            GoodsUtils.DrawRewards(jsonData.rewards)
        end

        if checkNumber(self._serverData.freeTimes) > 0 then
            self._serverData.freeTimes = checkNumber(self._serverData.freeTimes) - 1
        else
            GoodsUtils.DrawRewards({{
                goodsId = LanternRechargeUtils.GetConsumeId(),
                num = LanternRechargeUtils.GetConsumeNum() * -1
            }}, true)
        end

        if self._co ~= nil then
            cs_coroutine.stop(self._co)
            self._co = nil
        end
        if self._changeCo ~= nil then
            cs_coroutine.stop(self._changeCo)
            self._changeCo = nil
        end
        self._co = cs_coroutine.start(function()
            CfUtils.PlayAnimation(self.Root, "ActivityRechargeLotteryDialog121801Light")
            coroutine.yield(Yielders.GetWaitForSeconds(0.5))
            UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = jsonData.rewards, cb = function()
                CfUtils.PlayAnimation(self.Root, "ActivityRechargeLotteryDialog121801Switch")

                self._changeCo = cs_coroutine.start(function()
                    --coroutine.yield(Yielders.GetWaitForSeconds(0.7))
                    self:FillSelf()
                    self._isClick = false
                end)
            end } })
        end)

        local isCanDraw = ((checkNumber(self._serverData.freeTimes) > 0) or (GoodsUtils.GetThingNo(LanternRechargeUtils.GetConsumeId()) > 0)) 
        ActivityUtils.UpdateActivityMainRedPointState(self._data.id, isCanDraw and 0 or -1)
    end)
end

function LanternRechargeDialog:OnDestroy()
    local isCanDraw = ((checkNumber(self._serverData.freeTimes) > 0) or (GoodsUtils.GetThingNo(LanternRechargeUtils.GetConsumeId()) > 0)) 
    ActivityUtils.UpdateActivityMainRedPointState(self._data.id, isCanDraw and 0 or -1)
    
    if self._co ~= nil then
        cs_coroutine.stop(self._co)
        self._co = nil
    end
    if self._changeCo ~= nil then
        cs_coroutine.stop(self._changeCo)
        self._changeCo = nil
    end
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end

return LanternRechargeDialog
